"use strict";const utils=require("../utils");module.exports=(defaultFuncs,api,ctx)=>async function createPoll(threadID,questionText,options,callback){let resolveFunc=()=>{};let rejectFunc=()=>{};const returnPromise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});if(!callback){callback=(err,result)=>{if(err)return rejectFunc(err);resolveFunc(result)}}try{if(!ctx.mqttClient||!ctx.mqttClient.connected){throw new Error("Not connected to MQTT. Please use listenMqtt first.")}if(!threadID||typeof threadID!=="string"){throw new Error("Invalid threadID")}if(!questionText||typeof questionText!=="string"){throw new Error("questionText must be a string")}if(!Array.isArray(options)||options.length<2){throw new Error("options must be an array with at least 2 options")}if(typeof ctx.wsReqNumber!=="number")ctx.wsReqNumber=0;if(typeof ctx.wsTaskNumber!=="number")ctx.wsTaskNumber=0;const payload={epoch_id:utils.generateOfflineThreadingID(),tasks:[{failure_count:null,label:"163",payload:JSON.stringify({question_text:questionText,thread_key:threadID,options:options,sync_group:1}),queue_name:"poll_creation",task_id:++ctx.wsTaskNumber}],version_id:"34195258046739157"};const form=JSON.stringify({app_id:"772021112871879",payload:JSON.stringify(payload),request_id:++ctx.wsReqNumber,type:3});ctx.mqttClient.publish("/ls_req",form,{qos:1,retain:false},pubErr=>{if(pubErr){utils.error("createPoll",pubErr);callback(pubErr instanceof Error?pubErr:new Error(String(pubErr)))}else{callback(null,{success:true})}})}catch(err){utils.error("createPoll",err);callback(err)}return returnPromise};
